const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xfff4e6, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);

const rimLight = new THREE.PointLight(0xaad6ff, 0.45, 22);
rimLight.position.set(-4, 3, -5);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.32), keyLight, fillLight, rimLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(12, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.88, metalness: 0.03 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.2;
floor.receiveShadow = true;
scene.add(floor);

const gridHelper = new THREE.GridHelper(24, 48, 0xcfd8e6, 0xe6ecf5);
gridHelper.position.y = -1.19;
scene.add(gridHelper);

function createCombatant(robeColor, saberColor, x, z, facing) {
  const group = new THREE.Group();

  const robeMat = new THREE.MeshStandardMaterial({ color: robeColor, roughness: 0.95, metalness: 0.05 });
  const skinMat = new THREE.MeshStandardMaterial({ color: 0xffdbac, roughness: 0.65 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4, metalness: 0.6 });

  const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.42, 1.3, 16), robeMat);
  torso.position.y = 0.65;
  torso.castShadow = true;
  group.add(torso);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.2, 24, 24), skinMat);
  head.position.y = 1.45;
  head.castShadow = true;
  group.add(head);

  const hoodColor = robeColor === 0x1a1a1a ? 0x0a0a0a : 0x4a3c2a;
  const hood = new THREE.Mesh(
    new THREE.SphereGeometry(0.26, 24, 24, 0, Math.PI * 2, 0, Math.PI / 2),
    new THREE.MeshStandardMaterial({ color: hoodColor, roughness: 1.0 })
  );
  hood.position.y = 1.48;
  hood.rotation.x = Math.PI;
  hood.scale.y = 0.9;
  group.add(hood);

  const armGeo = new THREE.CylinderGeometry(0.09, 0.09, 0.75, 12);
  const leftArm = new THREE.Mesh(armGeo, robeMat);
  leftArm.position.set(-0.42, 1.05, 0);
  leftArm.rotation.z = Math.PI / 6;
  leftArm.castShadow = true;
  group.add(leftArm);

  const rightArm = new THREE.Mesh(armGeo, robeMat);
  rightArm.position.set(0.42, 1.05, 0);
  rightArm.rotation.z = -Math.PI / 6;
  rightArm.castShadow = true;
  group.add(rightArm);

  const saberGroup = new THREE.Group();
  const hilt = new THREE.Mesh(
    new THREE.CylinderGeometry(0.035, 0.035, 0.22, 12),
    darkMat
  );
  hilt.rotation.x = Math.PI / 2;
  saberGroup.add(hilt);

  const bladeGeo = new THREE.CylinderGeometry(0.025, 0.025, 1.15, 12);
  const bladeMat = new THREE.MeshStandardMaterial({
    color: saberColor,
    emissive: saberColor,
    emissiveIntensity: 3.0,
    toneMapped: false
  });
  const blade = new THREE.Mesh(bladeGeo, bladeMat);
  blade.position.z = 0.685;
  blade.rotation.x = Math.PI / 2;
  saberGroup.add(blade);

  const saberLight = new THREE.PointLight(saberColor, 4.0, 5);
  saberLight.position.z = 0.7;
  saberGroup.add(saberLight);

  saberGroup.position.set(0.48, 0.95, 0.25);
  saberGroup.rotation.y = -Math.PI / 3;
  group.add(saberGroup);

  group.position.set(x, -1.2, z);
  group.rotation.y = facing;

  return { mesh: group, saber: saberGroup, light: saberLight, rightArm: rightArm };
}

