const lightningGroup = new THREE.Group();
const lightningMat = new THREE.LineBasicMaterial({ color: 0xaaddff, transparent: true, opacity: 0.7 });
for(let i = 0; i < 4; i++) {
  const points = [];
  for(let j = 0; j < 12; j++) {
    points.push(new THREE.Vector3(1.8 - j * 0.12, 1.4 + Math.random() * 0.3, (Math.random() - 0.5) * 0.3));
  }
  const geo = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geo, lightningMat);
  lightningGroup.add(line);
}
lightningGroup.visible = false;
scene.add(lightningGroup);

const sparkCount = 60;
const sparkGeo = new THREE.BufferGeometry();
const sparkPos = new Float32Array(sparkCount * 3);
const sparkVel = new Array(sparkCount).fill(null);
sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPos, 3));
const sparkMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.06,
  transparent: true,
  opacity: 0,
  blending: THREE.AdditiveBlending
});
const sparks = new THREE.Points(sparkGeo, sparkMat);
scene.add(sparks);

const clashPoint = new THREE.Vector3();

function triggerClash() {
  for(let i = 0; i < sparkCount; i++) {
    sparkVel[i] = {
      x: (Math.random() - 0.5) * 0.2,
      y: (Math.random() - 0.2) * 0.2,
      z: (Math.random() - 0.5) * 0.2,
      life: 1.0
    };
    sparkPos[i * 3] = clashPoint.x + (Math.random() - 0.5) * 0.3;
    sparkPos[i * 3 + 1] = clashPoint.y + (Math.random() - 0.5) * 0.3;
    sparkPos[i * 3 + 2] = clashPoint.z + (Math.random() - 0.5) * 0.3;
  }
  sparkGeo.attributes.position.needsUpdate = true;
  anakin.light.intensity = 8.0;
  sidious.light.intensity = 8.0;
}

camera.position.set(0, 2.8, 6.5);
camera.lookAt(0, 0.8, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 0.8, 0);
controls.maxPolarAngle = Math.PI / 2 - 0.1;

let clashTimer = 0;
let isClashing = false;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  const combatPhase = t * 1.2;

  anakin.mesh.position.x = -1.4 + Math.sin(combatPhase) * 0.4;
  anakin.mesh.position.z = Math.cos(combatPhase * 1.3) * 0.6;
  anakin.mesh.rotation.y = Math.PI / 2 + Math.sin(combatPhase * 0.8) * 0.25;

  sidious.mesh.position.x = 1.4 + Math.cos(combatPhase * 0.9) * 0.3;
  sidious.mesh.position.z = Math.sin(combatPhase * 0.7) * 0.5;
  sidious.mesh.rotation.y = -Math.PI / 2 + Math.cos(combatPhase) * 0.3;

  anakin.saber.rotation.x = -Math.PI / 4 + Math.sin(combatPhase * 3) * 0.5;
  anakin.saber.rotation.z = Math.sin(combatPhase * 2.5) * 0.4;
  anakin.rightArm.rotation.z = -Math.PI / 6 + Math.sin(combatPhase * 3) * 0.3;

  sidious.saber.rotation.x = -Math.PI / 5 + Math.cos(combatPhase * 2.8) * 0.4;
  sidious.saber.rotation.z = Math.cos(combatPhase * 2.2) * 0.5;

  const dist = anakin.mesh.position.distanceTo(sidious.mesh.position);
  const swingAlign = Math.abs(Math.sin(combatPhase * 3));

  if(dist < 2.0 && swingAlign < 0.15 && !isClashing) {
    isClashing = true;
    clashPoint.copy(anakin.mesh.position).lerp(sidious.mesh.position, 0.5);
    clashPoint.y = 0.8 + Math.random() * 0.4;
    triggerClash();

    anakin.mesh.position.x -= 0.05;
    sidious.mesh.position.x += 0.05;
  } else if(swingAlign > 0.5) {
    isClashing = false;
  }

  for(let i = 0; i < sparkCount; i++) {
    if(sparkVel[i]) {
      sparkPos[i * 3] += sparkVel[i].x;
      sparkPos[i * 3 + 1] += sparkVel[i].y;
      sparkPos[i * 3 + 2] += sparkVel[i].z;
      sparkVel[i].y -= 0.015;
      sparkVel[i].life -= 0.025;
      if(sparkVel[i].life <= 0) sparkVel[i] = null;
    } else {
      sparkPos[i * 3 + 1] = -100;
    }
  }
  sparkGeo.attributes.position.needsUpdate = true;
  sparkMat.opacity = Math.max(0, (anakin.light.intensity - 3.0) / 5.0);

  anakin.light.intensity = 4.0 + Math.sin(t * 25) * 0.5;
  sidious.light.intensity = 4.0 + Math.cos(t * 22) * 0.5;

  if(Math.sin(t * 0.8) > 0.75) {
    lightningGroup.visible = true;
    lightningGroup.position.copy(sidious.mesh.position);
    lightningGroup.position.x -= 0.4;
    lightningGroup.position.y = -0.2;
    lightningGroup.children.forEach(bolt => {
      const pos = bolt.geometry.attributes.position.array;
      for(let j = 0; j < 12; j++) {
        pos[j * 3 + 1] = 1.6 + (Math.random() - 0.5) * 0.4;
        pos[j * 3 + 2] = (Math.random() - 0.5) * 0.4;
      }
      bolt.geometry.attributes.position.needsUpdate = true;
    });
  } else {
    lightningGroup.visible = false;
  }

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;

  camera.position.x = Math.sin(t * 0.15) * 0.3;
  camera.position.y = 2.8 + Math.sin(t * 0.2) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}

animate();

