const cityGroup = new THREE.Group();
scene.add(cityGroup);

function createBuildingLayer(count, minHeight, maxHeight, spread, yOffset, depthRange) {
  const geometries = [];
  const materials = [];

  for (let i = 0; i < count; i++) {
    const width = 0.8 + Math.random() * 2.5;
    const depth = 0.8 + Math.random() * 2.5;
    const height = minHeight + Math.random() * (maxHeight - minHeight);

    const geometry = new THREE.BoxGeometry(width, height, depth);
    geometry.translate(0, height / 2, 0);

    const x = (Math.random() - 0.5) * spread;
    const z = (Math.random() - 0.5) * spread;
    const y = yOffset;

    const matrix = new THREE.Matrix4();
    matrix.setPosition(x, y, z);

    const hue = Math.random() > 0.7 ? 0.55 + Math.random() * 0.1 : 0.6 + Math.random() * 0.05;
    const saturation = 0.1 + Math.random() * 0.15;
    const lightness = 0.7 + Math.random() * 0.2;
    const color = new THREE.Color().setHSL(hue, saturation, lightness);

    const material = new THREE.MeshStandardMaterial({
      color: color,
      roughness: 0.3 + Math.random() * 0.4,
      metalness: 0.4 + Math.random() * 0.4,
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(x, y, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    cityGroup.add(mesh);

    if (Math.random() > 0.6) {
      const windowGeo = new THREE.BoxGeometry(width * 0.9, height * 0.8, depth * 1.01);
      const windowMat = new THREE.MeshBasicMaterial({
        color: new THREE.Color().setHSL(Math.random() > 0.5 ? 0.1 : 0.55, 0.8, 0.6),
        transparent: true,
        opacity: 0.3 + Math.random() * 0.4
      });
      const windows = new THREE.Mesh(windowGeo, windowMat);
      windows.position.set(x, y + height / 2, z);
      cityGroup.add(windows);
    }

    if (height > 15 && Math.random() > 0.8) {
      const antennaGeo = new THREE.CylinderGeometry(0.05, 0.1, 3, 8);
      const antennaMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, metalness: 0.8, roughness: 0.2 });
      const antenna = new THREE.Mesh(antennaGeo, antennaMat);
      antenna.position.set(x, y + height + 1.5, z);
      cityGroup.add(antenna);

      const lightGeo = new THREE.SphereGeometry(0.15, 8, 8);
      const lightMat = new THREE.MeshBasicMaterial({ color: 0xff0044 });
      const beacon = new THREE.Mesh(lightGeo, lightMat);
      beacon.position.set(x, y + height + 3, z);
      cityGroup.add(beacon);
    }
  }
}

