const trafficGroup = new THREE.Group();
scene.add(trafficGroup);

const trafficCount = 60;
const trafficMeshes = [];
const trafficData = [];

for (let i = 0; i < trafficCount; i++) {
  const size = 0.1 + Math.random() * 0.15;
  const geometry = new THREE.SphereGeometry(size, 8, 8);
  const material = new THREE.MeshBasicMaterial({
    color: new THREE.Color().setHSL(Math.random() * 0.1 + 0.05, 1, 0.6)
  });
  const mesh = new THREE.Mesh(geometry, material);

  const lane = Math.floor(Math.random() * 6);
  const height = 15 + lane * 8 + Math.random() * 4;
  const radius = 20 + Math.random() * 40;
  const speed = 0.2 + Math.random() * 0.3;
  const angle = Math.random() * Math.PI * 2;

  mesh.position.set(Math.cos(angle) * radius, height, Math.sin(angle) * radius);
  trafficGroup.add(mesh);

  trafficMeshes.push(mesh);
  trafficData.push({ radius, height, speed, angle, lane });
}

const platformGeo = new THREE.CylinderGeometry(4, 4, 0.5, 32);
const platformMat = new THREE.MeshStandardMaterial({ color: 0x8899aa, roughness: 0.6, metalness: 0.5 });
const platform = new THREE.Mesh(platformGeo, platformMat);
platform.position.set(0, 35, 0);
platform.receiveShadow = true;
cityGroup.add(platform);

const domeGeo = new THREE.SphereGeometry(3.5, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
const domeMat = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  metalness: 0.1,
  roughness: 0.05,
  transmission: 0.6,
  thickness: 0.5,
  transparent: true,
  opacity: 0.3
});
const dome = new THREE.Mesh(domeGeo, domeMat);
dome.position.set(0, 35.25, 0);
cityGroup.add(dome);

camera.position.set(45, 30, 45);
camera.lookAt(0, 20, 0);

let controls;
if (typeof OrbitControls !== 'undefined') {
  controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.05;
  controls.autoRotate = true;
  controls.autoRotateSpeed = 0.3;
  controls.target.set(0, 20, 0);
  controls.minDistance = 20;
  controls.maxDistance = 100;
  controls.maxPolarAngle = Math.PI / 2 - 0.05;
}

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  trafficData.forEach((data, i) => {
    data.angle += data.speed * 0.02;
    const mesh = trafficMeshes[i];
    mesh.position.x = Math.cos(data.angle) * data.radius;
    mesh.position.z = Math.sin(data.angle) * data.radius;

    if (Math.random() > 0.99) {
      mesh.material.color.setHSL(Math.random() * 0.1 + 0.05, 1, 0.6);
    }
  });

  rimLight.intensity = 0.6 + Math.sin(t * 0.5) * 0.2;
  rimLight.position.y = 40 + Math.sin(t * 0.3) * 5;

  if (controls) controls.update();
  renderer.render(scene, camera);
}
animate();

